class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int sumOfNumbers(int l, int r, int k) {
    long count = r - l + 1, digitSum = (long) (l + r) * count / 2;
    long repunit = (pow(10, k) - 1 + MOD) % MOD * pow(9, MOD - 2) % MOD;
    return (int) (digitSum % MOD * pow(count, k - 1) % MOD * repunit % MOD);
  }
}
